// game-decl.mjs - The editor's address book for web/game: translate-tg.mjs hands it every top-level rt.type and rt.def,
// and it writes build/game-decl/ (not part of the build; nothing the game runs reads it):
//   game.d.ts (+ .map)     one interface per DM type (its vars and procs, `extends` its parent), each global proc as a
//                          function, GLOB's names, and DMProcThis: each proc's path -> the type its `this` is
//   runtime.d.ts (+ .map)  the runtime as game files see it (web/game/tsconfig.json maps #runtime here): all of runtime.ts,
//                          with rt.def giving the proc's `this` its type
// The maps point each name back at its rt.type or rt.def line, so the editor's "go to definition" on this.update_icon(),
// a global proc or a var lands in the game file. Vars and procs are `any`: only the names are known (and DM lets a subtype
// have a var named like its parent's proc).
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { relative, resolve } from "node:path";
import ts from "typescript";

const types = new Map(); // path -> { parent, members: [[name, file, line, col, isProc]] }
const globalProcs = []; // [name, file, line, col]
const procThis = []; // [path, type]
const typeOf = (p) => types.get(p) ?? types.set(p, { parent: undefined, members: [] }).get(p);
const strArg = (n) => (n && ts.isStringLiteral(n) ? n.text : null);

/** one top-level rt.type(...) or rt.def(...) call of file f (sf: its source file) */
export function addDecl(f, sf, call) {
	const kind = call.expression.name.text, at = (n) => sf.getLineAndCharacterOfPosition(n.getStart(sf));
	if (kind === "type") { // rt.type([id,] path, parent, { vars })
		const a = call.arguments, i = a.findIndex((x) => ts.isStringLiteral(x));
		if (i < 0) return;
		const t = typeOf(a[i].text);
		t.parent = strArg(a[i + 1]);
		const vars = a.slice(i + 1).find((x) => ts.isObjectLiteralExpression(x));
		if (vars) for (const p of vars.properties) {
			if (!p.name || !(ts.isIdentifier(p.name) || ts.isStringLiteral(p.name))) continue;
			const { line, character } = at(p.name);
			t.members.push([p.name.text, f, line, character, false]);
		}
	} else if (kind === "def") {
		const path = strArg(call.arguments[0]);
		if (!path) return;
		const k = Math.max(path.lastIndexOf("/proc/"), path.lastIndexOf("/verb/"));
		if (k < 0) return;
		const tp = path.slice(0, k), name = path.slice(k + 6), { line } = at(call);
		if (tp === "") globalProcs.push([name, f, line, 0]);
		else { typeOf(tp).members.push([name, f, line, 0, true]); procThis.push([path, tp]); }
	}
}

const ident = (p) => "DM" + p.replace(/[^A-Za-z0-9_]/g, "$");
const okName = (n) => /^[A-Za-z_$][\w$]*$/.test(n);
const key = (n) => (okName(n) ? n : JSON.stringify(n));
const B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const vlq = (v) => { let n = v < 0 ? ((-v) << 1) | 1 : v << 1, s = ""; do { let d = n & 31; n >>>= 5; if (n) d |= 32; s += B64[d]; } while (n); return s; };
/** a source map with, per generated line, one segment at its name's column pointing at [file, line, col] (or none) */
function sourceMap(dir, name, maps) {
	const sources = [], idx = new Map();
	let pf = 0, pl = 0, pc = 0;
	const segs = maps.map((m) => {
		if (!m) return "";
		const [col, f, line, scol] = m;
		let k = idx.get(f);
		if (k === undefined) { k = sources.length; idx.set(f, k); sources.push(relative(dir, f)); }
		const s = vlq(col) + vlq(k - pf) + vlq(line - pl) + vlq(scol - pc);
		pf = k; pl = line; pc = scol;
		return s;
	});
	return JSON.stringify({ version: 3, file: name, sourceRoot: "", sources, names: [], mappings: segs.join(";") });
}

/** writes dir/{game,runtime}.d.ts and their maps; globals: GLOB's names; runtimeTs: src/translate/runtime.ts. Returns counts. */
export function writeDecls(dir, globals, runtimeTs) {
	mkdirSync(dir, { recursive: true });
	const text = [], maps = [];
	const emit = (s, src = null, col = 0) => { text.push(s); maps.push(src ? [col, ...src] : null); };
	emit("// Generated by web/tools/translate-tg.mjs (game-decl.mjs): the editor's names for web/game. Not part of the build.");
	for (const [p, t] of types) {
		emit(`interface ${ident(p)}${t.parent && types.has(t.parent) ? ` extends ${ident(t.parent)}` : ""} {`);
		const procs = new Set(t.members.filter((m) => m[4]).map((m) => m[0]));
		for (const [n, f, l, c, isProc] of t.members) if (isProc || !procs.has(n)) emit(`\t${key(n)}: any;`, [f, l, c], 1);
		emit("}");
	}
	emit("interface DMProcThis {");
	for (const [path, tp] of procThis) emit(`\t${JSON.stringify(path)}: ${ident(tp)};`);
	emit("}");
	for (const n of ["parent_proc", "new_", "each", "list", "prob", "pick"]) emit(`declare function ${n}(...args: any[]): any;`); // the bundle lowers these
	for (const [n, f, l, c] of globalProcs) if (okName(n)) emit(`declare function ${n}(...args: any[]): any;`, [f, l, c], 17);
	emit("interface DMGlobals {");
	for (const n of globals) if (okName(n)) emit(`\t${n}: any;`);
	emit("}");
	emit("declare const GLOB: DMGlobals;");
	emit("//# sourceMappingURL=game.d.ts.map");
	writeFileSync(resolve(dir, "game.d.ts"), text.join("\n") + "\n");
	writeFileSync(resolve(dir, "game.d.ts.map"), sourceMap(dir, "game.d.ts", maps));
	const defLine = readFileSync(runtimeTs, "utf8").split("\n").findIndex((l) => l.startsWith("export function def("));
	const rel = relative(dir, runtimeTs).replace(/\.ts$/, ".js");
	const shim = [
		`export * from ${JSON.stringify(rel)};`,
		`import type { Frame } from ${JSON.stringify(rel)};`,
		"type DMThisOf<P> = P extends keyof DMProcThis ? DMProcThis[P] : any;",
		"export function def<P extends string>(path: P, fn?: (this: DMThisOf<P>, f: Frame, ...args: any[]) => any, gen?: boolean, meta?: object): void;",
		"//# sourceMappingURL=runtime.d.ts.map",
	];
	writeFileSync(resolve(dir, "runtime.d.ts"), shim.join("\n") + "\n");
	writeFileSync(resolve(dir, "runtime.d.ts.map"), sourceMap(dir, "runtime.d.ts", shim.map((l) => (l.startsWith("export function def") ? [16, runtimeTs, defLine, 16] : null))));
	return { types: types.size, procs: procThis.length + globalProcs.length };
}
